"""Little Roots: short, playful activities for 3 and 4 year olds, done by a grown-up with the child.
Written for Bright Roots.

The category is the area of learning. The areas loosely follow Realising the Ambition (Scotland) and
the EYFS: Talk, Early maths, Letters and sounds, Moving, Creating, The world around us and Feelings and
friends. The words are our own; only the headings are borrowed. The rhymes are written for Bright Roots too.
"""
from make_starters import _item

TALK = "Talk"
MATHS = "Early maths"
SOUNDS = "Letters and sounds"
MOVING = "Moving"
CREATING = "Creating"
WORLD = "The world around us"
FEELINGS = "Feelings and friends"
PE = "P.E."
OUTDOORS = "Outdoors"
LIFE = "Life skills"
COOKING = "Cooking"
CRAFTS = "Crafts"
RHYMES = "Rhymes and songs"


def _little(slug, title, emoji, category, minutes, summary, materials, steps, talk, more, easier, safety, story):
    """`story` is read aloud in the story book: an opening, one line for each step, then an ending."""
    assert len(story) == len(steps) + 2, slug
    data = _item("little", slug, title, emoji, category, minutes, "easy", 3, None, summary, materials, steps, safety)
    data.update({"talk": talk, "more": more, "easier": easier, "story": story})
    return data


