    _little(
        "little-kindness-jar", "Kindness jar", "🫙", FEELINGS, 10,
        "Every time someone in the family does something kind, add a pom-pom or paper star to the jar and fill it up together.",
        [("1", "clear plastic jar or tub"), ("lots", "of paper stars or large pom-poms, bigger than a 50p coin"),
         ("1", "felt-tip pen and sticky label")],
        ["Decorate the jar together and stick a label on it: our kindness jar.",
         "Talk about what kindness is: helping, sharing, saying something nice, giving a hug.",
         "Each time someone is kind, they get to put a star in the jar. Say what the kind thing was.",
         "At bedtime, look at the jar together and remember the kind things from today.",
         "When the jar is full, celebrate together with something special, like a picnic or a story party."],
        ["What kind thing did you do today?",
         "What kind thing did someone do for you?",
         "How did it make you feel?"],
        "Write each kind thing on the paper star before it goes in, and read them all out when the jar is full.",
        "Spot one kind thing a day and add a star together. Grown-ups can add stars for kind things they notice too.",
        "Use paper stars or big pom-poms, not small beads or buttons, which are a choking risk. Use a plastic jar, not glass.",
        ["In the kitchen sat an empty jar. \"I wish I could be full of something lovely,\" it said.",
         "Let's make it our kindness jar! A label, some stickers, and it's ready.",
         "What is kindness? Helping, sharing, a hug, a kind word.",
         "You helped tidy up! That was kind. Pop a star in the jar.",
         "At bedtime, let's look. One star, two stars, three stars. So much kindness today!",
         "When the jar is full, we'll have a special celebration.",
         "Day by day, the jar filled up with stars. \"Now I'm full of the loveliest thing of all,\" it smiled. \"Kindness!\""],
    ),
    _little(
        "little-sharing-toys", "Sharing toys", "🤝", FEELINGS, 10,
        "Practise sharing with teddy and a timer, so everyone gets a turn with the favourite toy.",
        [("1", "favourite toy"), ("1", "teddy or doll"), ("1", "sand timer or kitchen timer")],
        ["Sit with your child and Teddy. Teddy wants a go with the favourite toy too!",
         "Talk about sharing: we can take turns so everyone gets to play.",
         "Set the timer. Your child plays first. When it rings, it's Teddy's turn.",
         "Help your child pass the toy to Teddy. Praise them: \"That was kind sharing!\"",
         "When the timer rings again, Teddy gives it back. Talk about how waiting felt."],
        ["How do you think Teddy feels when he gets a turn?",
         "Was it hard to wait? What helped?",
         "Who could we share with at home?"],
        "Practise with a sibling or friend, using the timer. Or share a snack, cutting it in half fairly.",
        "Keep turns very short, like ten seconds, and give lots of praise. Sharing is hard at this age, so any try counts.",
        "Choose a toy that's safe and bigger than your child's fist. Stay calm if there are tears, as sharing is a big skill.",
        ["Here's your favourite toy. But oh! Teddy wants to play with it too.",
         "What can we do? We can share! We take turns, so everyone gets to play.",
         "You go first. The timer is ticking. Play, play, play!",
         "Ding! The timer rang. Now it's Teddy's turn. Can you pass it to him?",
         "Teddy is so happy. And look, now it's your turn again!",
         "Taking turns means everyone gets to play.",
         "Teddy gave you a big hug. \"Thank you for sharing,\" he said. \"You're a kind friend.\""],
    ),
    _little(
        "little-saying-sorry", "Saying sorry", "💗", FEELINGS, 10,
        "Use puppets or teddies to act out little accidents, and practise saying sorry and making it better.",
        [("2", "teddies, puppets or dolls"), ("1", "block tower or toy to knock over"), ("1", "plaster or tissue for pretend")],
        ["Set up the two teddies playing together, with one building a tower.",
         "Make one teddy knock the tower down by accident. How does the other teddy feel?",
         "Ask your child: \"What could the teddy say?\" Practise saying sorry together.",
         "Talk about making it better too: helping to build it again, or giving a hug.",
         "Act out another little accident, like a bump, and let your child help the teddies make up."],
        ["How does Teddy feel when his tower falls down?",
         "What could the other teddy say?",
         "How can we make it better?"],
        "Talk about a time your child said sorry, or a time someone said sorry to them, and how it felt.",
        "Just let the teddies say sorry and hug. Your child can join the hug.",
        "Keep it gentle and playful. Never force a sorry. Feeling it matters more than saying it.",
        ["Bunny and Bear were playing together. Bear was building a tall, tall tower.",
         "Bunny hopped too close and... crash! The tower fell down.",
         "Bear felt sad. His lip wobbled. \"My tower!\"",
         "What could Bunny say? \"Sorry, Bear. I didn't mean to.\"",
         "\"Let's build it again together,\" said Bunny. And they did, even taller!",
         "Saying sorry and helping can make a sad friend feel better.",
         "Bear smiled and gave Bunny a big hug. \"That's what friends do,\" he said. \"Thank you for saying sorry.\""],
    ),
