        "Float a leaf or a stick boat in a puddle, or draw round a puddle with chalk and see if it has shrunk later.",
        "Just stomp gently through one puddle together, holding hands.",
        "Check puddles with a stick first, avoid ones near roads where cars splash, and stay away from deep water "
